    "futureArchitectureNote": "FOLKOOP не будується як crypto-first продукт: не плануються FOLKOOP Coin, NFT-Passport або обов’язковий криптогаманець. PostgreSQL залишається основною операційною базою; криптографічний або ledger-якір можливий лише як додатковий шар цілісності, якщо виникне реальна задача довіри.",
