    "physicalLayerText": "Centerit, kumppanipaikat, työkalut ja laitteet voidaan myöhemmin yhdistää Places-rakenteiden, QR/NFC:n ja tarkasti rajattujen käyttöoikeuksien avulla niin, että yhteistyögraafi heijastaa todellista maailmaa.",
    "futureArchitectureNote": "FOLKOOP ei ole crypto-first: suunnitelmissa ei ole FOLKOOP Coinia, NFT-Passportia eikä pakollista kryptolompakkoa. PostgreSQL säilyy operatiivisena totuuden lähteenä; kryptografinen tai ledger-ankkurointi on vain mahdollinen eheyskerros, jos todellinen luottamusongelma sitä vaatii.",
    "futureArchitectureLink": "Lue tekninen arkkitehtuuri GitHubissa",
    "cityMissingTitle": "Valitse kaupunkisi",
    "cityMissingText": "Aseta kaupunkisi Profiilissa ennen paikallisten kaupunkityökalujen avaamista.",
