    "cityUnsupportedText": "Nykyinen kansalaispilotti on yhdistetty Göteborgiin. Valittu kaupunki tallennetaan, mutta FOLKOOP ei näytä Göteborgin paikallisia tietoja ikään kuin ne koskisivat toista kaupunkia.",
    "menu": "Valikko",
