    "futureArchitectureNote": "FOLKOOP ليس منتجًا crypto-first: لا توجد خطة لـ FOLKOOP Coin أو NFT-Passport أو محفظة عملات مشفرة إلزامية. تبقى PostgreSQL مصدر الحقيقة التشغيلي؛ أما التثبيت التشفيري أو على ledger فهو مجرد طبقة سلامة محتملة إذا ظهرت مشكلة ثقة حقيقية.",
