    "noDrafts": "Weli qabyo ma jiraan",
    "noDraftsText": "Ka bilow wax aad jeclaan lahayd inaad dad kale la samayso. Qabyadu waa gaar ilaa adeeg dhab ah oo daabacaad la xiro.",
    "peopleTitle": "Dad, ma aha profile-yo keliya",
    "peopleText": "Shabakadda mustaqbalka waxay isku xiri doontaa dadka iyo bulshooyinka iyada oo loo marayo danaha, xirfadaha iyo hawlaha wadajirka ah. Noocan weli ma laha diiwaan xubno dhab ah ama farriimo.",
    "togetherTitle": "Wax yar bay fududahay marka la wada sameeyo",
    "togetherText": "Codso caawin, soo bandhig xirfad, qorshee iib wadajir ah ama wadaag qalab. Noocan waxaad diyaarin kartaa qabyo gaar ah; dalabyo ama lacag-bixin lama diro.",
    "projectsTitle": "Fikrad ilaa mashruuc wadajir ah",
    "projectsText": "Sharax hadafka iyo dadka ama kheyraadka uu u baahan yahay. Kuwani waa qabyooyinkaaga, ma aha mashaariic dadweyne oo leh ka qaybgalayaal diiwaangashan.",
    "centerTitle": "Meel lagu kulmo nolosha dhabta ah",
    "centerText": "Kulamo, barasho, qalab iyo caawimo bini’aadan. Tani waa fikradda Xarunta: weli ma sheeganno goob furan, qalab la heli karo ama barnaamij la xaqiijiyey.",
    "centerCard1": "Kulmo oo baro",
    "centerCard1Text": "Miisas wada-hadal, aqoon-is-weydaarsiyo hal-abuur leh iyo dhacdooyin ay ka qaybgalayaashu hoggaamiyaan.",
    "centerCard2": "Samee oo wadaag",
    "centerCard2Text": "Qalab wadaag ah, kulamo mashruuc iyo goobo shuraako.",
    "centerCard3": "Soo-dhaweyn bini’aadan",
    "centerCard3Text": "Martigeliye dadka ka caawiya inay is helaan oo ay qaadaan tallaabada xigta.",
    "centerOnlineTitle": "Xarunta onlaynka · dadka, magaalada iyo mashaariicda hal jid",
    "centerOnlineText": "Xaruntu waxay isku xirtaa bulshada deegaanka, dadka, ilaha Magaalada iyo mashaariicda si loo helo tallaabooyin xiga oo cad. v0-kan waa onlayn/isku-dhaf; ma sheeganayno in xarun jireed oo FOLKOOP ahi furan tahay.",
    "centerOnlineStatus": "Xarunta onlaynka v0 · hagitaan isku xiran",
    "centerMuraStatus": "Sheekada Mura · tusaale",
    "centerPeopleTitle": "Hel qof ama xirfad",
    "centerPeopleText": "Adeegso Dadka iyo Bulshooyinka marka tallaabada xigta ee waxtarka leh ay tahay qof, xirfad ama wada hadal caadi ah.",
    "centerCityTitle": "Hel ilo magaalo ama lammaane",
    "centerCityText": "Adeegso waddooyinka Magaalada ee leh ilo cad iyo adeegyada dibadda adigoon FOLKOOP u ekaysiin hay’ad dowladeed.",
    "centerProjectTitle": "U beddel ficil wadajir ah",
    "centerProjectText": "Adeegso Baahi, Bixin ama Mashruuc marka tallaabada xigta ay u baahan tahay isku-duwid cad, ee aysan ahayn wada hadal keliya.",
    "centerCommunityTitle": "Bulshada caadiga ahi sidoo kale waa muhiim",
    "centerCommunityText": "Wada hadal, is-caawin, ka-mid-noqosho iyo aqoon deegaan looma baahna inay dhammaantood noqdaan hawlo.",
    "centerHostTitle": "Hagitaan bini’aadan",
    "centerHostText": "Habka Host waa Soo dhawayn → Oggolaansho → Baahi → Iswaafajin → Gudbin → Dabagal. v0-kan ma ballanqaadayo adeeg Host oo shaqaale leh; maanta adeegso waddooyinka isku xiran.",
    "centerLocalTitle": "Xaaladda bulshada deegaanka Göteborg",
    "centerLocalText": "ГБГ Форум waa bulsho dibadeed oo ka jirta Göteborg. FOLKOOP ma soo dejiyo mana waafajiyo xubnaheeda ama farriimaheeda.",
    "centerLocalExternal": "Fur ГБГ Форум",
    "centerLocalExternalNote": "Bulsho Telegram dibadeed · ma jiro isku-dubarid akoon ama xog FOLKOOP.",
    "centerLocalIllustrative": "Sheekada Mura, xaaladdan deegaanka waxaa lagu muujiyey dad iyo farriimo tusaale ahaan loo qoray. Waxba lagama koobiyeeyo forum-ka dhabta ah.",
    "centerOtherCityTitle": "Xaaladda Xarunta deegaanka weli halkan kuma xirna",
    "centerOtherCityText": "FOLKOOP ma tusi doono xaaladda bulshada Göteborg sidii inay ka tirsan tahay magaalo kale.",
    "centerPhysicalTitle": "Goobo jireed iyo goobo lammaane",
    "centerPhysicalText": "Xarun jireed oo joogto ah ama lammaane la leh weli waa arrin mustaqbal ah oo ku xiran lammaanayaal. Ma sheeganayno in goob FOLKOOP ahi furan tahay.",
    "proposeEvent": "Samee qabyo fikrad dhacdo",
