    "profileLink": "Fur Profile",
    "future": "La qorsheeyey · lama xirin",
    "messageText": "Wadahadallada gaarka ah iyo kuwa kooxdu waxay ka tirsan yihiin FOLKOOP. Waxay u baahan yihiin akoonno server, gudbin, xakamayn asturnaanta iyo dhexdhexaadin. Noocani ma iska dhigayo inuu farriimo dirayo.",
