    "mission": "Uma baahnin inaan isku mid noqono si aan wadajir u falno.",
    "missionBody": "FOLKOOP wuxuu dadka kala duwan ka caawiyaa inay helaan dano wadaag ah, isku geeyaan kheyraadka oo wada shaqeeyaan. Iskaashigu wuxuu ka kooban yahay caawimada maalinlaha ah, shaqo, mashaariic iyo nolosha magaalada — ma aha iibsi keliya.",
