    "repeatTutorial": "Hordhaca mar kale muuji",
    "aboutTitle": "Ku saabsan FOLKOOP",
    "aboutText": "FOLKOOP waa shabakad iskaashi: ka bilow waxa aad u baahan tahay, bixin karto ama rabto inaad qabato, dabadeed hel dadka, kheyraadka iyo tallaabada xigta ee cad.",
    "futureArchitectureTitle": "Halka uu FOLKOOP u kori karo",
    "futureArchitectureText": "Pilot-ka hadda jira wuu fududaanayaa. Haddii isticmaalka dhabta ahi muujiyo baahi, FOLKOOP wuxuu ku dari karaa kalsooni la qaadi karo, wakiillo ammaan ah oo ficil sameeya, iskaashi u dhexeeya node-yo magaalo oo madax-bannaan iyo xiriir dijitaal ah oo lala yeesho goobaha iyo kheyraadka la wadaago ee dunida dhabta ah.",
    "trustLayerTitle": "Kalsooni iyo Passport",
    "trustLayerText": "Doorarka la qaadi karo, taariikhda ka-qaybgalka iyo aqoonsiyada la xaqiijin karo waxay caddeyn karaan waxa ficil gaar ahi u baahan yahay iyada oo dadka aan loo rogin hal dhibcood oo caalami ah.",
    "agentLayerTitle": "Wakiilka ficilka",
    "agentLayerText": "Wakiil FOLKOOP oo mustaqbalka ah wuxuu caawin karaa helidda dadka, kheyraadka iyo tallaabada xigta, diyaarinta ficillada iyo sharaxaadda isku-aadka. Ficillada muhiimka ahi weli waxay u baahan yihiin oggolaanshaha qofka.",
    "networkLayerTitle": "Shabakad furan oo magaalooyinka u dhexeysa",
    "networkLayerText": "Node-yada FOLKOOP ee madax-bannaan waxay mustaqbalka wadaagi karaan mashruucyo dadweyne oo la doortay, fursado iyo aqoonsiyo la qaadi karo iyaga oo aan dhammaan magaalooyinka gelin hal keyd xogeed oo dhexe.",
    "physicalLayerTitle": "Jireed ↔ dijitaal",
    "physicalLayerText": "Xarumaha, goobaha wada-hawlgalayaasha, qalabka iyo agabka waxaa mustaqbalka lagu xiriirin karaa Places, QR/NFC iyo nidaamyo gelitaan oo si taxaddar leh loo xaddiday si graph-ka iskaashigu u muujiyo dunida dhabta ah.",
    "futureArchitectureNote": "FOLKOOP ma aha crypto-first: lama qorshaynayo FOLKOOP Coin, NFT-Passport ama wallet crypto oo khasab ah. PostgreSQL ayaa ahaanaya isha xogta hawlgalka; xidhitaanka cryptographic ama ledger-ku waa oo keliya lakab suuragal ah oo ilaalinta xogta ah marka dhibaato kalsooni oo dhab ahi jirto.",
    "futureArchitectureLink": "Ka akhri qaab-dhismeedka farsamo GitHub",
