    "cityUnsupportedText": "Tijaabada bulshada ee hadda jirta waxay ku xiran tahay Göteborg. Magaalada aad dooratay waa la kaydiyaa, laakiin FOLKOOP ma soo bandhigi doono xogta maxalliga ah ee Göteborg sidii inay magaalo kale quseyso.",
