      "me": "Ku qor oo keliya waxa caawiya iskaashiga: magac ama naanays, magaalo, xirfado iyo isbarasho gaaban. Muuqaalka diiwaanka adiga ayaa dooranaya.",
      "home": "Bogga hore waa dulmar ficil-ku-horreeyo, ma aha qulqul aan dhammaan. Ka bilow wax aad u baahan tahay, bixin karto ama rabto inaad dhisto.",
      "messages": "Farriimaha waxaa ku jira wada-hadallo toos ah, kooxeed iyo kuwa shaqada iskaashiga. Farriimaha tijaabadu server-ka ayay ku kaydsan yihiin, laakiin weli ma leh sirgelin end-to-end ah.",
