    "local": "Pêşnivîsa taybet · nehat weşandin",
    "memory": "Tenê ji bo vê danişînê. Nûkirina rûpelê karê nehilanînî digire. Ji bo parastinê hilanîna li ser amûrê di Profîlê de çalak bike.",
