    "noDraftsText": "Bi tiştekî dest pê bike ku dixwazî bi kesên din re bikî. Pêşnivîs taybet e heta ku servîsa rastîn a weşandinê were girêdan.",
    "peopleTitle": "Mirov, ne tenê profîl",
    "peopleText": "Tora pêşerojê dê mirov û civakan bi eleqe, şiyan û karên hevpar ve girêde. Di vê guhertoyê de hê pelrêça endamên rastîn an peyam tune.",
    "togetherTitle": "Bi hev re hinek hêsantir e",
    "togetherText": "Alîkarî bixwaze, şiyanekê pêşkêş bike, kirîna hevpar plan bike an amûran parve bike. Di vê guhertoyê de dikarî pêşnivîsên taybet amade bikî; ferman an dravdan nayên şandin.",
    "projectsTitle": "Ji fikrê ber bi projeya hevpar",
    "projectsText": "Armanc û mirov an çavkaniyên ku pêwîst in rave bike. Ev pêşnivîsên te ne, ne projeyên giştî yên bi beşdarên qeydkirî.",
    "centerTitle": "Cihek ji bo hevdîtina di jiyana rastîn de",
    "centerText": "Hevdîtin, fêrbûn, amûr û alîkariya mirovî. Ev konsepta Navendê ye: em hê dibêjin ku cihê vekirî, amûrên berdest an bernameya piştrastkirî heye.",
    "centerCard1": "Hev bibînin û fêr bibin",
