    "aboutTitle": "Derbarê FOLKOOP de",
    "aboutText": "FOLKOOP tora hevkariyê ye: bi tiştê ku pêwîst e, dikarî pêşkêş bikî an dixwazî bikî dest pê bike, paşê mirov, çavkanî û gava paşîn a zelal bibîne.",
    "futureArchitectureTitle": "FOLKOOP dikare ber bi ku ve pêş bikeve",
    "futureArchitectureText": "Pilota heyî hêsan dimîne. Heke bikaranîna rastîn pêdiviyê nîşan bide, FOLKOOP dikare baweriyeke veguhêzbar, agentên ewle yên çalakiyê, hevkarî di navbera nodeyên bajarî yên serbixwe û girêdaneke dîjîtal bi cih û çavkaniyên hevpar ên cîhana rastîn re zêde bike.",
    "trustLayerTitle": "Bawerî û Passport",
    "trustLayerText": "Rolên veguhêzbar, dîroka beşdariyê û belgeyên ku dikarin bêne verastkirin dikarin tiştê ji bo çalakiyeke taybet pêwîst e îspat bikin bêyî ku mirovan bikin yek puana gerdûnî.",
    "agentLayerTitle": "Agenta çalakiyê",
    "agentLayerText": "Agenta FOLKOOP ya pêşerojê dikare alîkarî bike ku mirov, çavkanî û gavên din bêne dîtin, çalakiyan amade bike û sedemên lihevhatinê rave bike. Çalakiyên girîng hîn jî pejirandina mirovan dixwazin.",
    "networkLayerTitle": "Tora vekirî di navbera bajaran de",
    "networkLayerText": "Nodeyên FOLKOOP yên serbixwe dikarin paşê projeyên giştî yên hilbijartî, derfet û belgeyên veguhêzbar parve bikin bêyî ku hemû bajar di yek database-a navendî de bên komkirin.",
    "physicalLayerTitle": "Fîzîkî ↔ dîjîtal",
    "physicalLayerText": "Navend, cihên hevkar, amûr û alav dikarin paşê bi Places, QR/NFC û pergalên gihîştinê yên bi baldarî sînorkirî bên girêdan da ku grafa hevkariyê cîhana rastîn nîşan bide.",
    "futureArchitectureNote": "FOLKOOP bernameyeke crypto-first nîne: FOLKOOP Coin, NFT-Passport an jî wallet-a kripto ya mecbûr ne di planê de ne. PostgreSQL çavkaniya sereke ya operasyonal dimîne; anchor-a cryptographic an ledger tenê dema ku pirsgirêkeke rastîn a baweriyê hebe dikare bibe qatêk zêde ya yekparebûnê.",
    "futureArchitectureLink": "Mîmariya teknîkî li GitHub bixwîne",
